import numpy as np
a=np.array(g,dtype=int).copy()  # g = test input from earlier
H,W=a.shape
lines=[]
# find 3x3 solid blocks
for r in range(H-2):
    for c in range(W-2):
        v=a[r,c]
        if v!=0 and (a[r:r+3,c:c+3]==v).all():
            lines.append((v,r+1,c+1))
print(lines)
out=a.copy()
for v,lr,lc in lines:
    out[lr,:]=v
    out[:,lc]=v
# intersections of different-color lines -> 0
cells={}
for v,lr,lc in lines:
    cells.setdefault('row',{})[lr]=v
    cells.setdefault('col',{})[lc]=v
for r,vr in cells['row'].items():
    for c,vc in cells['col'].items():
        if vr!=vc: out[r,c]=0
for row in out.tolist(): print(row)
